let sourcePromise;
const T={
 en:{title:'POI functions and local concentrations',intro:'One source inventory, compared within the two Figure 5 outlines.',wider:'Wider area',primary:'Primary area',objects:'mapped destinations',density:'POIs / ha',mix:'Function mix',function:'Function',count:'Count',share:'Share',bands:'Where functions concentrate',bandNote:'Three equal northing bands within the wider outline. Density uses each clipped band’s land area.',band:'Band',local:'Local function clusters',localNote:'100 m cells with at least 5 POIs, at least 3 of the category and relative concentration ≥1.5. This describes local specialization.',near:'Cell around',relative:'Relative concentration',method:'Relative concentration = category share in the cell / category share in the wider area. Source objects use their mapped point or a documented representative point. Original IDs, tags and the node/area merge audit remain available.',coverage:'OSM records show mapped activities. They do not measure all businesses, jobs, floor area or opening-hour demand.',source:'Source and method',food:'Food & drink',work:'Work & services',building:'Building-use context',finding:(n,p,r,food)=>n+' destinations are recorded in the wider area and '+p+' in the primary area. Primary-area POI density is '+r+'× the wider-area density; food and drink form '+food+'% of its records.',office:(x)=>'Source building-use attributes assign '+x+'% of the wider area’s floor proxy to offices. Together with the POIs, this supports a business district with strong food, shopping and service activity. The floor proxy is separate from POI counts.'},
 zh:{title:'POI 功能与局部集聚',intro:'同一份来源清单，在任务书的两个范围内分别比较。',wider:'外围区',primary:'重点区',objects:'已记录目的地',density:'POI / ha',mix:'功能构成',function:'功能',count:'记录数',share:'占比',bands:'功能在哪里集中',bandNote:'按外围区南北坐标等分为三段，密度分母采用各段与边界相交后的面积。',band:'分段',local:'局部功能集聚',localNote:'100 m 网格内至少 5 条 POI、某类至少 3 条，且相对集聚度 ≥1.5。用于描述局部功能偏向。',near:'网格附近场所',relative:'相对集聚度',method:'相对集聚度＝网格内某类占比／外围区该类占比。记录使用源点位或注明方法的代表点；保留原始 ID、标签和点面重复核对表。',coverage:'OSM 反映已记录的活动，不能据此推算全部商户、就业、楼面面积或分时需求。',source:'来源与方法',food:'餐饮',work:'办公与服务',building:'建筑用途对照',finding:(n,p,r,food)=>'外围区记录 '+n+' 条目的地，重点区 '+p+' 条。重点区 POI 密度是外围区的 '+r+' 倍，其中餐饮占 '+food+'%。',office:(x)=>'建筑源属性中，外围区办公用途占楼面代理量的 '+x+'%。结合 POI，可将场地理解为以商务活动为背景、餐饮、零售及服务较强的地区。楼面代理量与 POI 记录数分别计算。'},
 ja:{title:'POIの機能と局所的な集中',intro:'一つの出典リストを、図5の二つの区域内で比較。',wider:'周辺区域',primary:'重点区域',objects:'記録された目的地',density:'POI / ha',mix:'機能構成',function:'機能',count:'件数',share:'比率',bands:'機能の集中',bandNote:'周辺区域を北距座標で三分割。密度は各帯と区域の重なり面積を使用。',band:'帯',local:'局所的な機能の集中',localNote:'100 m格子内にPOIが5件以上、該当機能が3件以上、相対集中度が1.5以上。記述的な比較。',near:'格子付近の場所',relative:'相対集中度',method:'相対集中度＝格子内の機能比率／周辺区域内の同比率。出典の点または記録した代表点を使用。元のIDとタグを保持。',coverage:'OSMは記録済みの活動を示す。全事業所、雇用、床面積、時間帯別需要の調査ではない。',source:'出典と方法',food:'飲食',work:'業務とサービス',building:'建物用途の対照',finding:(n,p,r,food)=>'周辺区域に'+n+'件、重点区域に'+p+'件の目的地。重点区域のPOI密度は周辺区域の'+r+'倍で、飲食が'+food+'%を占める。',office:(x)=>'建物用途の出典属性では、周辺区域の床面積代理値の'+x+'%がオフィス。POIと合わせ、業務を背景に飲食・小売・サービスが集まる地区と読める。'}
};
function el(tag,text,cls){const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x;}
function table(headers,rows){const wrap=el('div',undefined,'poi-table-wrap'),t=el('table'),h=el('tr');headers.forEach(x=>h.append(el('th',x)));const head=el('thead');head.append(h);t.append(head);const body=el('tbody');rows.forEach(row=>{const tr=el('tr');row.forEach(x=>tr.append(el('td',String(x))));body.append(tr);});t.append(body);wrap.append(t);return wrap;}
export async function renderPOI(host,lang='en'){
 if(!host)return;const l=T[lang]||T.en;host.dataset.language=lang;
 try{
 sourcePromise ||= fetch('study-atlas/poi_semantics.json?v=20261018-brief5-poi',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('POI '+r.status);return r.json();});
 const d=await sourcePromise;if(!host.isConnected||host.dataset.language!==lang)return;
 const w=d.scopes.study_area,p=d.scopes.primary_brief,food=p.categories.find(x=>x.id==='food'),label=c=>c.label[lang]||c.label.en;
 host.replaceChildren(el('p','POI SEMANTICS / OSM · 2026.10.18','kicker'),el('h3',l.title),el('p',l.intro));
 const stats=el('div',undefined,'poi-stats');for(const [name,s] of [[l.wider,w],[l.primary,p]]){const card=el('div');card.append(el('span',name),el('strong',String(s.poi_count)),el('span',l.objects),el('b',s.poi_per_ha.toFixed(2)+' '+l.density));stats.append(card);}host.append(stats,el('p',l.finding(w.poi_count,p.poi_count,(p.poi_per_ha/w.poi_per_ha).toFixed(2),food.share_pct.toFixed(1)),'poi-finding'));
 if(d.building_use_context?.office_floor_proxy_share_pct!==undefined)host.append(el('h4',l.building),el('p',l.office(d.building_use_context.office_floor_proxy_share_pct.toFixed(1))));
 host.append(el('h4',l.mix));
 const bars=el('div',undefined,'poi-mix');for(const [name,s] of [[l.wider,w],[l.primary,p]]){const row=el('div');row.append(el('strong',name));const bar=el('div',undefined,'poi-stacked');for(const c of s.categories){if(!c.count)continue;const part=el('span');part.style.width=c.share_pct+'%';part.style.background=c.color;part.title=label(c)+': '+c.count+' ('+c.share_pct.toFixed(1)+'%)';part.setAttribute('aria-label',part.title);bar.append(part);}row.append(bar);bars.append(row);}host.append(bars);
 const cats=[...w.categories].sort((a,b)=>b.count-a.count);host.append(table([l.function,l.wider+' · '+l.count,l.wider+' · '+l.share,l.primary+' · '+l.count,l.primary+' · '+l.share],cats.map(c=>{const pp=p.categories.find(x=>x.id===c.id);return [label(c),c.count,c.share_pct.toFixed(1)+'%',pp.count,pp.share_pct.toFixed(1)+'%'];})));
 host.append(el('h4',l.bands),el('p',l.bandNote),table([l.band,l.count,l.density,l.food,l.work],w.sectors.map((s,i)=>[lang==='zh'?['南段 · 新日本桥侧','中段 · 鍛冶町／神田侧','北段 · 岩本町侧'][i]:s.sector,s.poi_count,s.poi_per_ha.toFixed(2),s.mix.find(x=>x.category==='food').share_pct.toFixed(1)+'%',s.mix.find(x=>x.category==='work').share_pct.toFixed(1)+'%'])));
 const clusters=['food','retail','health','work'].map(k=>d.local_concentrations.find(c=>c.scope==='study_area'&&c.category===k)).filter(Boolean);
 host.append(el('h4',l.local),el('p',l.localNote),table([l.function,l.near,l.count,l.relative],clusters.map(c=>[label(w.categories.find(x=>x.id===c.category)),c.name_examples[0],c.category_count+' / '+c.total_pois,c.location_quotient.toFixed(2)+'×'])),el('p',l.method,'poi-method'),el('p',l.coverage,'poi-method'));
 const source=el('div',undefined,'poi-source');source.append(el('strong',l.source));
 for(const [name,url] of [['OpenStreetMap contributors · ODbL','https://www.openstreetmap.org/copyright'],['POI inventory + original IDs','study-atlas/tables/poi_inventory.csv'],['Classification, spatial methods + source date','study-atlas/poi_semantics.json']]){const a=el('a',name);a.href=url;source.append(a);}host.append(source);
 }catch(e){host.replaceChildren(el('p',e.message));}
}

